package com.example.projetomarvel;
import android.graphics.*;import android.util.LruCache;import java.util.*;import static com.example.projetomarvel.WorldValues.*;
/** Pixel art uses the same shapes, palettes, orientations and animation frames as Web. */
final class WorldArt {
 android.content.res.AssetManager assets;
 final WorldRules rules;final WorldMap map;final Paint p=new Paint();
 final LruCache<String,Bitmap>chunks=new LruCache<>(12),sprites=new LruCache<>(180),props=new LruCache<String,Bitmap>(20*1024*1024){protected int sizeOf(String key,Bitmap b){return b.getByteCount();}};
 WorldArt(WorldRules r,WorldMap m){rules=r;map=m;rules.global.let("noise",(Fn)a->terrainNoise(integer(a[0]),integer(a[1]),a.length>2?integer(a[2]):0));rules.global.let("this",obj(kv("map",map)));rules.global.let("TILE",obj(kv("WATER",0),kv("SAND",1),kv("GRASS",2),kv("PATH",3),kv("CITY",4),kv("BRIDGE",5),kv("RUINS",6),kv("WAKANDA",7),kv("ASGARD",8)));p.setFilterBitmap(false);}
 Bitmap chunk(int x,int y){String key=x+","+y;Bitmap b=chunks.get(key);if(b!=null)return b;try{if(assets!=null){try(java.io.InputStream in=assets.open("visit_world/terrain/"+x+"-"+y+".png")){b=BitmapFactory.decodeStream(in);chunks.put(key,b);return b;}}}catch(java.io.IOException ignored){}b=Bitmap.createBitmap(512,512,Bitmap.Config.RGB_565);WorldCanvas c=new WorldCanvas(new Canvas(b));for(int dy=0;dy<16;dy++)for(int dx=0;dx<16;dx++)rules.run("draw_tile",c,x*16+dx,y*16+dy,dx*32,dy*32);chunks.put(key,b);return b;}
 void sprite(Canvas c,Object character,float x,float y,String dir,double time,boolean walking,float scale){
  int phase=walking?(int)Math.floor(time*9)%4:0,breath=!walking&&Math.sin(time*2.3)>.85?1:0,blink=!walking&&(int)Math.floor(time*1.3)%6==5?1:0;
  String key=WorldJson.write(character)+"|"+dir+"|"+walking+"|"+phase+"|"+breath+"|"+blink;
  Bitmap b=sprites.get(key);if(b==null){b=Bitmap.createBitmap(40,46,Bitmap.Config.ARGB_8888);WorldCanvas ctx=new WorldCanvas(new Canvas(b));rules.run("drawSprite",ctx,character,20,42,dir,time,walking,1);sprites.put(key,b);}
  c.save();c.translate(x-20*scale,y-42*scale);c.scale(scale,scale);c.drawBitmap(b,0,0,p);c.restore();
 }
 void prop(Canvas canvas,Object prop,double time){String kind=str(get(prop,"kind"));boolean dynamic=Arrays.asList("steam","aurora","fissure","orb","fountain").contains(kind);float x=(float)number(get(prop,"x")),y=(float)number(get(prop,"y")),w=(float)number(get(prop,"w")),h=(float)number(get(prop,"h"));
  if(dynamic){rules.run("draw_prop",new WorldCanvas(canvas),prop,time);return;}
  String key=WorldJson.write(prop);Bitmap b=props.get(key);int left=80,top=110;if(b==null){b=Bitmap.createBitmap(Math.max(1,(int)w+160),Math.max(1,(int)h+220),Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.translate(left-x,top-y);rules.run("draw_prop",new WorldCanvas(c),prop,0);props.put(key,b);}canvas.drawBitmap(b,x-left,y-top,p);
 }
 void rect(Canvas c,float x,float y,float w,float h,int color){p.setColor(color);c.drawRect(x,y,x+w,y+h,p);}
 void render(Canvas c,Map<String,Object>s,List<Object>npcs,List<Object>objects,float width,float height,double time,Object nearest,String target){
  float cx=Math.round(map.cameraX),cy=Math.round(map.cameraY);c.drawColor(0xff305b73);for(int y=(int)Math.floor(cy/512);y<=(cy+height)/512;y++)for(int x=(int)Math.floor(cx/512);x<=(cx+width)/512;x++)c.drawBitmap(chunk(x,y),x*512-cx,y*512-cy,p);c.save();c.translate(-cx,-cy);
  for(int y=(int)(cy/32);y<(cy+height)/32;y++)for(int x=(int)(cx/32);x<(cx+width)/32;x++)if(map.at(x,y)==0&&noise(x,y,8)>.7)rect(c,x*32+(int)((time*3+x)%16),y*32+19,7,1,0x5c76a5b7);
  List<Object>layers=new ArrayList<>();for(Object o:map.props){float x=(float)number(get(o,"x")),y=(float)number(get(o,"y")),w=(float)number(get(o,"w")),h=(float)number(get(o,"h"));if(x+w>cx-80&&x-w<cx+width+80&&y+h>cy-110&&y-h<cy+height+110)layers.add(obj(kv("type","prop"),kv("value",o),kv("depth",get(o,"depth"))));}
  for(Object o:objects)layers.add(obj(kv("type","object"),kv("value",o),kv("depth",get(o,"py"))));for(Object n:npcs)layers.add(obj(kv("type","npc"),kv("value",n),kv("depth",get(n,"py"))));if(s!=null)layers.add(obj(kv("type","player"),kv("value",s),kv("depth",get(get(s,"player"),"y"))));
  layers.sort(Comparator.comparingDouble(v->number(get(v,"depth"))));for(Object l:layers){Object o=get(l,"value");String type=str(get(l,"type"));if(type.equals("prop")){prop(c,o,time);continue;}if(type.equals("player")){Object a=get(o,"player");sprite(c,get(o,"character"),(float)number(get(a,"x")),(float)number(get(a,"y")),str(get(a,"direction")),time,truth(get(a,"walking")),1.2f);continue;}float x=(float)number(get(o,"px")),y=(float)number(get(o,"py"));if(x<cx-50||x>cx+width+50||y<cy-80||y>cy+height+50)continue;if(type.equals("object"))rules.run("draw_object",new WorldCanvas(c),o,time,s);else{double phase=0;for(char ch:str(get(o,"id")).toCharArray())phase+=ch; sprite(c,rules.run("npcCharacter",o),x,y,str(get(o,"direction")),time+phase/7,truth(get(o,"walking")),1.2f);}}
  Map<String,Object>flags=s==null?obj():map(s.get("flags"));for(Object g:map.gates)if(!truth(flags.get(str(get(g,"flag"))))){float x=(float)number(get(g,"x")),y=(float)number(get(g,"y")),w=(float)number(get(g,"w")),h=(float)number(get(g,"h"));if(truth(get(g,"vertical"))){rect(c,x,y,w,h,0xff686785);rect(c,x,y,3,h,0xffe3ce92);for(int i=0;i<h;i+=24)rect(c,x-6,y+i,w+12,5,0xffa5a4bc);}else{rect(c,x,y,w,7,0xff67668d);rect(c,x,y,w,2,0xffddd1a0);for(int i=0;i<w;i+=24){rect(c,x+i,y-20,7,30,0xff545776);rect(c,x+i-1,y-22,9,4,0xffbeaf77);}rect(c,x,y-13,w,12,0x60969bdd);}}
  String[][]effects={{"NY-02","fragment","#67b9ef"},{"WK-02","childSafe","#e5c569"},{"WK-03","flowerGiven","#da99c0"},{"BR-01","loki","#aee0ef"},{"LV-04","scarlet","#ea94b6"}};for(String[]e:effects)if(truth(flags.get(e[1]))){Map<String,Object>r=map.region(cx,cy);if(e[0].equals(r.get("id")))for(int k=0;k<7;k++)rect(c,(float)(number(r.get("x"))+8+k)*32,(float)(number(r.get("y"))+15)*32+(int)(Math.sin(time*2+k)*5),2,2,WorldCanvas.color(e[2]));}
  if(s!=null&&truth(flags.get("breach"))){Map<String,Object>r=map.byId("LV-01");List<Object>cast=list(rules.run("breachCast",s));for(int i=0;i<cast.size();i++){Object v=cast.get(i),npc=map.npcs.stream().filter(n->equal(get(n,"id"),get(v,"id"))).findFirst().orElse(null),charData=npc!=null?rules.run("npcCharacter",npc):rules.run("heroById",get(v,"id"));if(charData!=null){c.saveLayerAlpha(null,truth(get(v,"full"))?255:90);sprite(c,charData,((float)number(r.get("x"))+4+i*2.25f)*32,((float)number(r.get("y"))+18)*32,"up",time,false,1.2f);c.restore();}}}
  if(target!=null)for(Object n:npcs)if(target.equals(get(n,"id"))){float x=(float)number(get(n,"px")),y=(float)number(get(n,"py"));int bob=(int)Math.floor(Math.sin(time*3)*2);rect(c,x-1,y-49+bob,2,5,0xfffff0aa);rect(c,x-1,y-42+bob,2,2,0xfffff0aa);}
  if(nearest!=null){float x=(float)number(get(nearest,"px")),y=(float)number(get(nearest,"py"));rect(c,x-10,y-56,20,10,0xff142e30);rect(c,x-9,y-55,18,8,0xfff5e7b9);rect(c,x-3,y-48,4,4,0xfff5e7b9);for(int i=0;i<3;i++)rect(c,x-5+i*4,y-52,2,2,0xff29443c);}c.restore();
 }
 static double terrainNoise(int x,int y,int seed){int n=(x+seed*31)*374761393+(y+seed*7)*668265263;n=(n^(n>>>13))*1274126177;return ((n^(n>>>16))&0xffffffffL)/4294967295d;}
 double noise(int x,int y,int seed){return terrainNoise(x,y,seed);}
 void mini(Canvas c,Map<String,Object>s,float w,float h,boolean large){c.drawColor(0xff304c56);float sx=w/map.cols,sy=h/map.rows;Set<String>seen=new HashSet<>();for(Object id:list(s.get("discovered")))seen.add(str(id));for(int y=0;y<map.rows;y++)for(int x=0;x<map.cols;x++){int tile=map.at(x,y);if(tile==0)continue;Map<String,Object>r=map.tileRegions[y*map.cols+x];boolean known=seen.contains(str(r.get("id")));int color=known?(tile==5?0xffcbbb93:tile==3?0xffd9c69b:WorldCanvas.color(str(r.get("color")))):0xff49605e;rect(c,(float)Math.floor(x*sx),(float)Math.floor(y*sy),(float)Math.ceil(sx),(float)Math.ceil(sy),color);}if(large)for(Object ro:map.regions){Map<String,Object>r=map(ro);boolean known=seen.contains(str(r.get("id")));p.setColor(known?0xfff7ebbc:0xff80918a);p.setTypeface(Typeface.SERIF);p.setTextSize(9);p.setTextAlign(Paint.Align.CENTER);c.drawText(known?str(r.get("id")):"?",(float)(number(r.get("x"))+number(r.get("w"))*.5)*sx,(float)(number(r.get("y"))+number(r.get("h"))*.4)*sy,p);}
  Object t=rules.run("targetLocation",s);if(t!=null)rect(c,(float)number(get(t,"x"))*sx-2,(float)number(get(t,"y"))*sy-2,4,4,0xffebcf82);Object player=s.get("player");float px=(float)number(get(player,"x"))/32*sx,py=(float)number(get(player,"y"))/32*sy;rect(c,px-3,py-3,6,6,0xff273637);rect(c,px-2,py-2,4,4,0xfffff2ca);
 }
}
